func TestPipeOrder(t *testing.T) {
	checkLeak(t)

	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)

	write, events := goob.NewPipe(ctx)

	write(1)
	write(2)
	write(3)

	if 1 != <-events {
		t.Fatal()
	}
	if 2 != <-events {
		t.Fatal()
	}
	if 3 != <-events {
		t.Fatal()
	}
}

func TestPipe(t *testing.T) {
	checkLeak(t)

	const pipeCount = 10
	const msgCount = 10

	round := func() {
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()

		write, events := goob.NewPipe(ctx)

		wg := sync.WaitGroup{}
		wg.Add(msgCount)
		for i := 0; i < msgCount*2; i++ {
			if i%2 == 0 {
				go write(i)
			} else {
				go func() {
					<-events
					wg.Done()
				}()
			}
		}
		wg.Wait()
	}

	wg := sync.WaitGroup{}
	wg.Add(pipeCount)
	for i := 0; i < pipeCount; i++ {
		go func() {
			round()
			wg.Done()
		}()
	}
	wg.Wait()
}

func TestPipeCancel(t *testing.T) {
	checkLeak(t)

	const count = 1000

	for i := 0; i < count; i++ {
		ctx, cancel := context.WithCancel(context.Background())
		write, _ := goob.NewPipe(ctx)
		go write(1)
		go cancel()
	}
}

func TestPipeMonkey(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)

	write, events := goob.NewPipe(ctx)

	round := 30
	count := 10000

	for i := 0; i < round; i++ {
		go func() {
			for i := 0; i < count; i++ {
				write(i)
			}
		}()
	}

	for i := 0; i < count*round; i++ {
		time.Sleep(100 * time.Nanosecond)
		<-events
	}
